export type Combatant = {
    id: string;
    name?: string;
    team: number;
    kind: string;
    x: number;
    z: number;
    radius: number;
    health: number;
    maxHealth: number;
    dead: boolean;
    targetable: boolean;
    ultimateMeter: number;
    angle: number;
    statuses: Record<string, number>;
    modifiers: Record<string, Record<string, number>>;
};
export type Ability = {
    id: string;
    name: string;
    short: string;
    basic?: boolean;
    ultimate?: boolean;
    cooldown: number;
    cooldownKey?: string;
    effect: string;
    aim: string;
    range?: number;
    key: string;
    width?: number;
    radius?: number;
    angle?: number;
};
export type Definition = { id: string; name?: string; health: number; abilities: Ability[]; bonus?: Ability };
export type HitEvidence = {
    id: number;
    time: number;
    castId: number | null;
    targetId: string;
    x: number;
    z: number;
    amount: number;
    abilityId: string | null;
    name: string;
};
export type CastEvidence = {
    id: number;
    abilityId: string;
    name: string;
    accepted: boolean;
    reason: string;
    time: number;
    finished?: number;
    result: string;
    targetIds: string[];
    damage: number;
    ability: Ability;
    origin: { x: number; z: number };
    angle: number;
    target: { x: number; z: number } | null;
    pending: number;
};
export class CombatSimulation {
    constructor(definition?: unknown, training?: unknown, config?: unknown, map?: unknown);
    player: Combatant;
    targets: Combatant[];
    definition: Definition;
    stance: string | null;
    inWilderness: boolean;
    now: number;
    actionSerial: number;
    committedAngle: number;
    collisions: number;
    lastEvent: string;
    cooldowns: {
        ends: Record<string, number>;
        remaining(id: string, now: number): number;
        ready(id: string, now: number): boolean;
    };
    temporary: { available(id: string, now: number): boolean; grants: Map<string, { expires: number }> };
    journal: {
        latestAttempt: CastEvidence | null;
        latestAccepted: CastEvidence | null;
        latestResolution: CastEvidence | null;
        hits: HitEvidence[];
        attempts: CastEvidence[];
    };
    transactions: {
        time: number;
        sourceId: string | null;
        targetId: string;
        amount: number;
        abilityId: string | null;
        defeated: boolean;
    }[];
    weapons: { next: number; returning: boolean; blades: { x: number; z: number; phase: string }[] };
    projectiles: { items: { active: boolean; x: number; z: number; persistent?: boolean; phase?: string }[] };
    effects: { items: { active: boolean; x: number; z: number; range?: number; type: string }[] };
    activeAbilities(): Ability[];
    ability(id: string): Ability;
    cast(id: string, angle?: number, target?: { x: number; z: number }): boolean;
    damage(target: Combatant, amount: number, source?: Combatant): number;
    step(command: unknown, dt?: number): void;
}
